{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { useState, type FormEvent } from "react";
import { toast } from "sonner";
import { formatPrice } from "@/data/catalog";
import { COMPANY, DEFAULT_SALES_REP } from "@/data/company";
import { resolveLines, useStore } from "@/lib/store";

export const Route = createFileRoute("/account")({
  head: () => ({
    meta: [
      { title: "My Account | Pickrel Brothers Contractor Portal" },
      {
        name: "description",
        content:
          "Sign in to your Pickrel Brothers account to view order history, saved quotes, reorder lists and your assigned sales representative.",
      },
      { property: "og:title", content: "My Account | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Order history, quotes and reordering for Pickrel Brothers account customers.",
      },
    ],
  }),
  component: AccountPage,
});

function AccountPage() {
  const { session, signIn, signOut, orders, quotes, addToCart } = useStore();

  if (!session) return <SignIn onSignIn={signIn} />;

  return (
    <div className="container-page py-10">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="font-display text-3xl font-bold uppercase text-navy">My Account</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            {session.companyName} · Account {session.accountNumber} · {session.email}
          </p>
        </div>
        <div className="flex gap-3">
          {session.isAdmin && (
            <Link
              to="/admin"
              className="rounded-md border-2 border-navy px-4 py-2 text-sm font-semibold text-navy hover:bg-secondary"
            >
              Admin dashboard
            </Link>
          )}
          <button
            type="button"
            onClick={() => {
              signOut();
              toast.success("Signed out");
            }}
            className="rounded-md border border-input px-4 py-2 text-sm font-semibold text-muted-foreground hover:bg-secondary"
          >
            Sign out
          </button>
        </div>
      </div>

      <div className="mt-8 grid gap-8 lg:grid-cols-[1fr_320px]">
        <div className="space-y-8">
          <section className="rounded-md border border-border bg-card shadow-card">
            <h2 className="border-b border-border px-5 py-3 font-display text-lg font-bold uppercase text-navy">
              Order history
            </h2>
            {orders.length === 0 ? (
              <p className="px-5 py-8 text-sm text-muted-foreground">No orders yet.</p>
            ) : (
              <ul className="divide-y divide-border">
                {orders.map((o) => {
                  const lines = resolveLines(o.items);
                  return (
                    <li key={o.id} className="px-5 py-4">
                      <div className="flex flex-wrap items-center justify-between gap-3">
                        <div>
                          <p className="font-mono text-sm font-semibold text-foreground">{o.id}</p>
                          <p className="text-xs text-muted-foreground">
                            {new Date(o.createdAt).toLocaleDateString()} · PO {o.poNumber} · {o.status}
                          </p>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className="text-sm font-semibold text-foreground">
                            {formatPrice(o.total)}
                          </span>
                          <button
                            type="button"
                            onClick={() => {
                              o.items.forEach((l) => addToCart(l.slug, l.qty));
                              toast.success(`Order ${o.id} added to cart`);
                            }}
                            className="text-sm font-semibold text-sky hover:underline"
                          >
                            Reorder
                          </button>
                        </div>
                      </div>
                      <ul className="mt-2 text-xs text-muted-foreground">
                        {lines.map((l) => (
                          <li key={l.slug}>
                            {l.qty} × {l.product.name}
                          </li>
                        ))}
                      </ul>
                    </li>
                  );
                })}
              </ul>
            )}
          </section>

          <section className="rounded-md border border-border bg-card shadow-card">
            <h2 className="border-b border-border px-5 py-3 font-display text-lg font-bold uppercase text-navy">
              Saved quotes
            </h2>
            {quotes.length === 0 ? (
              <p className="px-5 py-8 text-sm text-muted-foreground">
                No quote requests yet.{" "}
                <Link to="/quote" className="font-semibold text-sky hover:underline">
                  Request a quote
                </Link>
                .
              </p>
            ) : (
              <ul className="divide-y divide-border">
                {quotes.map((q) => (
                  <li key={q.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4">
                    <div>
                      <p className="font-mono text-sm font-semibold text-foreground">{q.id}</p>
                      <p className="text-xs text-muted-foreground">
                        {q.jobName} · {new Date(q.createdAt).toLocaleDateString()} · {q.items.length} items
                      </p>
                    </div>
                    <span className="rounded-full bg-sky-soft px-3 py-1 text-xs font-semibold text-navy">
                      {q.status}
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </div>

        <aside className="h-fit rounded-md border-2 border-sky bg-sky-soft p-6">
          <h2 className="font-display text-lg font-bold uppercase text-navy">Your sales representative</h2>
          <p className="mt-3 text-sm font-semibold text-navy">{DEFAULT_SALES_REP.name}</p>
          <p className="text-xs text-navy-muted">{DEFAULT_SALES_REP.title}</p>
          <div className="mt-4 flex flex-col gap-2">
            <a
              href={DEFAULT_SALES_REP.phoneHref}
              className="rounded-md bg-navy px-4 py-2 text-center text-sm font-semibold text-navy-foreground hover:bg-navy-muted"
            >
              Call {DEFAULT_SALES_REP.phone}
            </a>
            <a
              href={`mailto:${DEFAULT_SALES_REP.email}`}
              className="rounded-md border-2 border-navy px-4 py-2 text-center text-sm font-semibold text-navy hover:bg-card"
            >
              Email your rep
            </a>
          </div>
          <p className="mt-4 text-xs text-navy-muted">{COMPANY.hours}</p>
        </aside>
      </div>
    </div>
  );
}

function SignIn({ onSignIn }: { onSignIn: (email: string, isAdmin?: boolean) => void }) {
  const [email, setEmail] = useState("");

  function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    onSignIn(email, email.trim().toLowerCase().startsWith("admin"));
    toast.success("Signed in");
  }

  return (
    <div className="container-page py-16">
      <div className="mx-auto max-w-md rounded-md border border-border bg-card p-8 shadow-card">
        <h1 className="font-display text-2xl font-bold uppercase text-navy">Account sign in</h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Account customers can view order history, saved quotes and reorder lists.
        </p>
        <form onSubmit={onSubmit} className="mt-6 space-y-4">
          <label className="block text-sm font-semibold text-navy">
            Email
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="mt-1 block h-11 w-full rounded-md border border-input bg-card px-3 text-sm text-foreground"
            />
          </label>
          <label className="block text-sm font-semibold text-navy">
            Password
            <input
              type="password"
              required
              className="mt-1 block h-11 w-full rounded-md border border-input bg-card px-3 text-sm text-foreground"
            />
          </label>
          <button
            type="submit"
            className="w-full rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
          >
            Sign in
          </button>
        </form>
        <p className="mt-4 text-xs text-muted-foreground">
          Demo sign-in: any email works. Use an address starting with "admin" to see the staff dashboard.
          No account yet? Call{" "}
          <a href={COMPANY.phoneHref} className="font-semibold text-sky">
            {COMPANY.phone}
          </a>{" "}
          to open one.
        </p>
      </div>
    </div>
  );
}
